export const SAT_JPEG_B64 = "";
export const SAT_MASK_B64 = "";
export const SAT_MASK_N = 176;
export function forestMaskAt(x, z) {
  if (!forestMaskAt._m) {
    const bin = atob(SAT_MASK_B64);
    const m = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) m[i] = bin.charCodeAt(i);
    forestMaskAt._m = m;
  }
  const u = ((x - 500) / 8800) + 0.5, v = ((z - 1700) / 8800) + 0.5;
  if (u < 0 || v < 0 || u >= 1 || v >= 1) return 0;
  return forestMaskAt._m[Math.floor(v * 176) * 176 + Math.floor(u * 176)];
}
